IPHY_PROTO_NAME = get_iphy_proxy_proto()
IPHY_LTE_RRC_PATTERN = r'"lte-rrc.(?:\S+?_\S+?_Message\S*?\.)?message".+size="(\d+?)".+pos="(\d+?)"'


class UesimPdmlParser(PdmlParser):

    def __init__(self):
        self.uesim_dump_path = os.environ.get('UESIM_DUMP_PATH', '/opt/emssim/util/uesim-dump')
        self.protocols_parsed_separately = ['m3ap', 's1ap', 'iphy', 'x2ap', 'lte_rrc', 'f1ap', 'e1ap',
                                            'nr-rrc', 'ngap', 'xnap']
        self.protocols_set = ['frame', 'eth', 'ip', 'udp', 'tcp', 'gtp', 'sctp']
        self.uesim_dump_supported_protocols = ['m3ap', 's1ap', 'x2ap', 'rrc', 'nas', '1x', 'hrpd', 'rrc5g',
                                               'f1ap', 'e1ap', 'ngap', 'xnap']
        self.supported_msg = {'M3': {'pattern': r'm3ap\.M3AP_PDU[\s\S]+?value="(\w+)"'},
                              'S1': {'pattern': r's1ap\.S1AP_PDU[\s\S]+?value="(\w+)"'},
                              'F1': {'pattern': r'f1ap\.F1AP_PDU[\s\S]+?value="(\w+)"'},
                              'E1': {'pattern': r'e1ap\.E1AP_PDU[\s\S]+?value="(\w+)"'},
                              'X2': {'pattern': r'x2ap\.X2AP_PDU[\s\S]+?value="(\w+)"'},
                              'NG': {'pattern': r'ngap\.NGAP_PDU[\s\S]+?value="(\w+)"'},
                              'Xn': {'pattern': r'\.XnAP_PDU[\s\S]+?value="(\w+)"'},
                              'I-PHY PoC RRC': {'pattern': '{iphy_proto}\.protocol\.type'.format(
                                  iphy_proto=IPHY_PROTO_NAME)}}

    class UesimHexMsg(object):
        def __init__(self, protocol, pdu_type, hex):
            self.protocol = protocol
            self.pdu_type = pdu_type
            self.hex = hex

        def dump_for_uesim(self):
            '''
            '''
            return '@dump %s %s %s' % (self.protocol, self.pdu_type, self.hex)

    def iter_msg(self, source):
        ''':param source: either string or file-like objects implementing read(size)'''
        for packet in self.iter_packets(source):
            for msg in self.get_converted_msgs_list(packet):
                yield msg

    def iter_packets(self, pdml_source):
        '''
        '''
        remaining = ""
        for chunk in self.iter_chunk(pdml_source):
            remaining = "".join([remaining, chunk])
            unparsed_part_index = 0
            for match in re.finditer(r'<packet>.*?</packet>', remaining, re.DOTALL):
                unparsed_part_index = match.end()
                yield match.group(0)
            remaining = remaining[unparsed_part_index:]

    def iter_chunk(self, file_or_string_data_source, chunk_size=4096):
        '''
        '''
        assert chunk_size > 0
        file_like_data_source = self.unify_read_api(file_or_string_data_source)
        return self._iter_chunk(file_like_data_source, chunk_size=chunk_size)

    def _iter_chunk(self, data_source, chunk_size=4096):
        '''
        '''
        while True:
            chunk = data_source.read(chunk_size)
            if not chunk:
                break
            yield chunk

    def unify_read_api(self, file_or_string_data_source):
        '''reading either from string or from file-like objects implementing read(size)'''
        if isinstance(file_or_string_data_source, basestring):
            string_data_source = py3_unicode(file_or_string_data_source)
            file_like_data_source = StringIO(string_data_source)
        else:
            file_like_data_source = file_or_string_data_source
        assert hasattr(file_like_data_source, "read")
        return file_like_data_source

    def _store_definition(self, definition_dict, container):
        definition_key, definition_payload = list(definition_dict.items())[0]
        if definition_key in container:
            if isinstance(container[definition_key], dict):
                definitions_list = [container.pop(definition_key)]
                container[definition_key] = definitions_list
            container[definition_key].append(definition_payload)
        else:
            container.update(definition_dict)

    def get_converted_msgs_list(self, packet):
        '''
        '''
        parsed_msgs = []
        uesim_hex_msgs = self._create_uesim_hex_msgs(packet)
        for uesim_hex_msg in uesim_hex_msgs:
            msg_meta_data = dict()
            self._parser_protocol_stack_and_return_last_definition(packet, container=msg_meta_data)
            asn_value_msg = self._convert_uesim_hex_msg2asn_value(uesim_hex_msg)
            lte_msg_payload = self._convert_asn_value2pythons_structure(asn_value_msg)
            lte_msg = self._create_message(lte_msg_payload, msg_meta_data)
            parsed_msgs.append(lte_msg)
        return parsed_msgs

    def _create_uesim_hex_msgs(self, tshark_packet):  # pragma: no mccabe
        m3_payloads_list = re.findall(self.supported_msg['M3']['pattern'], tshark_packet)
        if len(m3_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('m3ap', 'M3AP-PDU', m3_payloads_list[0]).dump_for_uesim()]
        s1_payloads_list = re.findall(self.supported_msg['S1']['pattern'], tshark_packet)
        if len(s1_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('s1ap', 'S1AP-PDU', s1_payloads_list[0]).dump_for_uesim()]
        f1_payloads_list = re.findall(self.supported_msg['F1']['pattern'], tshark_packet)
        if len(f1_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('f1ap', 'F1AP-PDU', f1_payloads_list[0]).dump_for_uesim()]
        e1_payloads_list = re.findall(self.supported_msg['E1']['pattern'], tshark_packet)
        if len(e1_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('e1ap', 'E1AP-PDU', e1_payloads_list[0]).dump_for_uesim()]
        ng_payloads_list = re.findall(self.supported_msg['NG']['pattern'], tshark_packet)
        if len(ng_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('ngap', 'NGAP-PDU', ng_payloads_list[0]).dump_for_uesim()]
        xn_payloads_list = re.findall(self.supported_msg['Xn']['pattern'], tshark_packet)
        if len(xn_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('xnap', 'XnAP-PDU', xn_payloads_list[0]).dump_for_uesim()]
        x2_payloads_list = re.findall(self.supported_msg['X2']['pattern'], tshark_packet)
        if len(x2_payloads_list) > 0:
            return [UesimPdmlParser.UesimHexMsg('x2ap', 'X2AP-PDU', x2_payload).dump_for_uesim()
                    for x2_payload in x2_payloads_list]
        iphy_protocol_occurences = re.findall(self.supported_msg['I-PHY PoC RRC']['pattern'], tshark_packet)
        if len(iphy_protocol_occurences) > 0:
            return [self._create_iphy_uesim_hex_msg(tshark_packet).dump_for_uesim()]
        raise MsgNotRecognized('Unknown message type. It has not been recognized. ', tshark_packet,
                               list(self.supported_msg.keys()))

    def _create_iphy_uesim_hex_msg(self, tshark_packet):
        HEXED_BYTE_LEN = 2
        regexp = '"{iphy_proto}\.data".+pos="(\d+?)".+value="(.+?)"'.format(iphy_proto=IPHY_PROTO_NAME)
        iphy_data_bytes_pos, iphy_data_value = re.search(regexp, tshark_packet).group(1, 2)
        lte_msg_bytes_quantity, lte_msg_bytes_pos = (int(x) for x in
                                                     re.search(IPHY_LTE_RRC_PATTERN,
                                                               tshark_packet).group(1, 2))
        # size is expressed in bytes, 1 byte = 2 hex signs
        pdu_type = re.search(r'showname="(.+?-Message(?:-.+?)?)"', tshark_packet).group(1)
        lte_rrc_message_signs_offset = HEXED_BYTE_LEN * (int(lte_msg_bytes_pos) - int(iphy_data_bytes_pos))
        last_index = lte_rrc_message_signs_offset + lte_msg_bytes_quantity * HEXED_BYTE_LEN + HEXED_BYTE_LEN
        payload = iphy_data_value[lte_rrc_message_signs_offset:last_index]

        return UesimPdmlParser.UesimHexMsg('rrc', pdu_type, payload)

    def _execute_uesim_process(self, uesim_hex_msg):
        p1 = subprocess.Popen(['/bin/echo', uesim_hex_msg], stdout=subprocess.PIPE)
        try:
            p2 = subprocess.Popen([self.uesim_dump_path], stdin=p1.stdout, stdout=subprocess.PIPE)
        except OSError as exc:
            if 'No such file or directory' in str(exc):
                print(
                    '\n\n###\nUesim-dump is not found. You can set path in environment variable "UESIM_DUMP_PATH" '
                    'if location is different then: /opt/emssim/util/uesim-dump\n###\n\n')
            raise
        p1.stdout.close()
        return p2.stdout.read()

    def _convert_uesim_hex_msg2asn_value(self, uesim_hex_msg):
        # HEXED_BYTE_LEN = 2
        command_output = self._execute_uesim_process(uesim_hex_msg).decode()
        if command_output.find("!!! syntax") != -1:
            raise UesimConverterError("Uesim-dump syntax error, msg: %s " % uesim_hex_msg)
        elif re.search(r"error: excessive 1 bytes or garbled PDU", command_output):
            # elif re.search(r"error: excessive (\d+) bytes or garbled PDU", command_output):
            #  legacy supported only single byte trailing, so not implementing more
            # cut_bytes = int(
            #     re.search(r"error: excessive (\d+) bytes or garbled PDU", command_output).group(1)) * HEXED_BYTE_LEN
            # return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-cut_bytes])
            return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-2])
        elif re.search(r"error: decoded \d+ bytes, out of \d+ \(1 left\)", command_output):
            # elif re.search(r"error: decoded \d+ bytes, out of \d+ \((\d+) left\)", command_output):
            # not supported in legacy but it is the same as above
            # cut_bytes = int(
            #     re.search(r"error: decoded \d+ bytes, out of \d+ \((\d+) left\)", command_output).group(
            #         1)) * HEXED_BYTE_LEN
            # return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-cut_bytes])
            return self._convert_uesim_hex_msg2asn_value(uesim_hex_msg[:-2])
        elif command_output.find("value") != -1:
            return command_output
        else:
            raise UesimConverterError("Uesim-dump msg: %s\n command output '%s'\n" % (uesim_hex_msg, command_output))

    def _convert_asn_value2pythons_structure(self, asn_value_msg):
        try:
            return ConvertAsnToPythonStructure(asn_value_msg).get()[0]
        except IndexError:
            raise AsnParserError('Asn value message has not been decoded')

    def _get_valid_protocols_set(self, packet):
        protocols_string = re.findall(r'"frame\.protocols"[\s\S]+?show="([\w\-_:]+?)"', packet)[0]
        valid_protocols = set([protocol for protocol in protocols_string.split(':')
                               if protocol not in self.protocols_parsed_separately])
        valid_protocols.update(['frame'])
        return valid_protocols

    def _parser_protocol_stack_and_return_last_definition(self, packet, container):
        packet_root = ET.fromstring(packet)
        last_protocol = container
        for protocol in packet_root:
            protocol_name = protocol.get('name')
            if protocol_name in self._get_valid_protocols_set(packet):
                protocol_definition = self._get_parsed_protocol(protocol_name, protocol)
                assert protocol_name not in last_protocol, "Definition should not override any other"
                last_protocol[protocol_name] = protocol_definition
                if self._is_protocol_not_duplicated(protocol_name, packet_root):
                    container[protocol_name] = protocol_definition
                last_protocol = protocol_definition
        return last_protocol

    def _get_stripped_field_name(self, protocol_name, field_node):
        return '%s' % re.findall(r'%s\.(\w+)' % protocol_name, field_node.get('name'))[0]

    def _get_parsed_protocol(self, protocol_name, protocol_node):
        protocol_def = dict()
        for field_node in protocol_node.findall('field'):
            name = field_node.get('name')
            if name and re.search('^{}\.'.format(protocol_name), name):
                protocol_def[self._get_stripped_field_name(protocol_name,
                                                           field_node)] = convert_data(field_node.get('show'))
        return protocol_def

    def _is_protocol_not_duplicated(self, protocol_name, packet_root):
        return True if len(packet_root.findall(".//proto[@name='%s']" % protocol_name)) == 1 else False

    def _create_message(self, pdu_dict, raw_meta_data):
        '''
        Create LTE message based on self.name and pdu_dict
        :param pdu_dict:
        :return:
        '''
        if pdu_dict is None:
            return None
        prepared_meta_data = {'occurrence_time': raw_meta_data['frame']['time_epoch']}

        msg = Message(pdu_dict, prepared_meta_data)

        return msg

    def _convert_nas_uesim_hex_2_pythons_structure(self, uesim_hex_msg):
        command_output = self._execute_uesim_process(uesim_hex_msg).decode()
        if re.search(r"!!! (syntax|error)", command_output):
            raise UesimConverterError("Uesim-dump error: {}".format(command_output))
        msg = command_output.split('\n---\n')[1].replace('\n...\n', '')
        return yaml.load(msg, Loader=yaml.BaseLoader)

    def parse_container(self, protocol, information_element, hex_to_be_parsed):
        '''
        :param protocol: e.g. rrc, s1ap, x2ap, m3ap, nas, 1x, hrpd, rrc5g
        :param information_element: expected to be stored inside container
        :param hex_to_be_parsed: hex to be parsed
        :return: MessageField encapsulating parsed rrc container
        '''
        protocol = str(protocol).lower()
        assert protocol in self.uesim_dump_supported_protocols, \
            "Protocol {} not supported by uesim-dump, allowed protocols {}".format(protocol,
                                                                                   self.uesim_dump_supported_protocols)
        hex_to_be_parsed = re.sub('0x', '', hex_to_be_parsed)
        uesim_hex = UesimPdmlParser.UesimHexMsg(protocol, information_element, hex_to_be_parsed).dump_for_uesim()
        if protocol == 'nas':
            return MessageField(self._convert_nas_uesim_hex_2_pythons_structure(uesim_hex))
        else:
            asn1_pdu = self._convert_uesim_hex_msg2asn_value(uesim_hex)
            return MessageField(self._convert_asn_value2pythons_structure(asn1_pdu))
